import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/software-exam/ispm/overview/comprehensive-exercises/","title":"7 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"7 综合练习","createTime":"2026-11-22T21:20:00.000Z","permalink":"/software-exam/ispm/overview/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":76.35,"words":22906},"git":{"createdTime":1795354081000},"filePathRelative":"software-exam/ispm/overview/7.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`7.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> 项目有明确的起点和终点，体现了项目的（ ）特性。</p><ul><li>A．独特性</li><li>B．临时性</li><li>C．渐进明细</li><li>D．及时性</li></ul><details class="quiz" data-q="1" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目的“临时性”是指项目有明确的起点和终点（开始时间和结束时间）</p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> 关于项目及项目管理基础的描述，正确的是（ ）。</p><ul><li>A．项目的“临时性”是指项目有明确的起点和终点，“临时性”一定意味着项目的持续时间短</li><li>B．项目管理作为一种管理方法体系，具有普适性，在不同国家、不同行业、项目管理不同发展阶段，在结构、内容、方法上是相同的</li><li>C．项目所产生的产品、服务或成果具有临时性特点</li><li>D．可交付成果可能是有形的，也可能是无形的。实现项目目标可能会产生一个或多个可交付成果</li></ul><details class="quiz" data-q="2" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：开展项目是为了通过可交付成果达成目标。目标是所指向的结果、要取得的战略地位、要达到的目的、要获得的成果、要生产的产品或者要提供的服务</p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 项目带来的效益可以是有形的、无形的或两者兼而有之，下列属于有形效益的是（ ）</p><ul><li>A．市场份额</li><li>B．商标</li><li>C．公共利益</li><li>D．战略联盟</li></ul><details class="quiz" data-q="3" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目带来的效益可以是有形的、无形的或两者兼而有之。有形效益的例子包括：货币资产、股东权益、公共事业、固定资产、工具、市场份额等</p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> 项目带来的效益可以是有形的、无形的或两者兼而有之，下列属于无形效益的是（ ）</p><ul><li>A．品牌认知度</li><li>B．货币资产</li><li>C．市场份额</li><li>D．工具</li></ul><details class="quiz" data-q="4" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目带来的效益可以是有形的、无形的或两者兼而有之。有形效益的例子包括：货币资产、股东权益、公共事业、固定资产、工具、市场份额等</p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 组织领导者启动项目是为了应对影响该组织持续运营和业务战略的因素。下列不属于引发项目因素的是（ ）。</p><ul><li>A．符合法律法规</li><li>B．满足干系人要求</li><li>C．调整组织结构</li><li>D．执行、变更业务</li></ul><details class="quiz" data-q="5" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：促进项目创建的因素大致可以分为四个基本类别：① 符合法律法规或社会需求；② 满足干系人要求或需求；③ 创造、改进或修复产品、过程或服务；④ 执行、变更业务或技术战略</p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 关于项目的描述，不正确的是（ ）。</p><ul><li>A．项目的“临时性”是指项目有明确的起点和终点</li><li>B．从业务价值角度看，项目旨在推动组织从一个状态转到另一个状态，从而达成特定目标，获得更高的业务价值</li><li>C．项目带来的效益可以是有形的、无形的或两者兼而有之</li><li>D．一个项目的人员数量至少为两人，可能涉及多个组织的多个单元</li></ul><details class="quiz" data-q="6" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目可能只涉及一个人，也可能涉及一组人；可能只涉及一个组织单元，也可能涉及多个组织的多个单元</p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 项目的（ ）是指项目有明确的起点和终点，但并不一定意味着项目的持续时间短</p><ul><li>A．临时性</li><li>B．长期性</li><li>C．确定性</li><li>D．持续性</li></ul><details class="quiz" data-q="7" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目的“临时性”是指项目有明确的起点和终点。“临时性”并不一定意味着项目的持续时间短</p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> 下列选项中，属于项目有形效益的是（ ）。</p><ul><li>A．固定资产和市场份额</li><li>B．声誉</li><li>C．品牌认知度</li><li>D．商誉</li></ul><details class="quiz" data-q="8" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目带来的效益可以是有形的、无形的或两者兼而有之。有形效益的例子包括：货币资产、股东权益、公共事业、固定资产、工具、市场份额</p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 关于项目“临时性”特征的描述，不正确的是（ ）。</p><ul><li>A．临时性意味着项目的持续时间短</li><li>B．临时性是指项目有明确的起点和终点</li><li>C．可交付成果可能会在项目终止后依然存在</li><li>D．临时性并不一定意味着项目的持续时间短</li></ul><details class="quiz" data-q="9" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：184-185。项目的“临时性”是指项目有明确的起点和终点。“临时性”并不一定意味着项目的持续时间短。虽然项目是临时性工作，但其可交付成果可能会在项目终止后依然存在</p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> 关于项目及项目管理基础的描述，不正确的是（ ）。</p><ul><li>A．项目是为提供一项独特产品、服务或成果所做的临时性努力</li><li>B．项目所产生的产品、服务或成果具有临时性特点</li><li>C．项目工作的目的在于得到特定的结果，即项目是而向目标的</li><li>D．项目管理和日常运营管理的目标有着本质的不同</li></ul><details class="quiz" data-q="10" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：虽然项目是临时性工作，但其可交付成果可能公在项目终止后依然存在。</p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> （ ）属于引发项目的因素。<br> ① 符合法律法规或社会需求<br> ② 满足干系人要求或需求<br> ③ 创造、改进或修复产品、过程或服务<br> ④ 执行、变更业务或技术战略</p><ul><li>A．①②③</li><li>B．①②</li><li>C．②③④</li><li>D．①②③④</li></ul><details class="quiz" data-q="11" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：促进项目创建的因素大致可以分为四个基本类别：① 符合法律法规或社会需求；② 满足干系人要求或需求；③ 创造、改进或修复产品、过程或服务；④ 执行、变更业务或技术战略</p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 关于项目的描述，不正确的是（ ）。</p><ul><li>A．项目的需求不复存在，是项目宣告结束的情况之一</li><li>B．实现项目目标可能会产生一个或多个可交付成果</li><li>C．可交付成果可能会在项目终止后依然存在</li><li>D．项目是为创造独特的产品、服务或成果而进行的周期性工作</li></ul><details class="quiz" data-q="12" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目是为创造独特的产品、服务或成果面进行的临时性工作。</p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> （ ）是将知识、技能、工具与技术应用于项目活动，以满足项目的要求，使组织能够有效并高效地开展项目。</p><ul><li>A．数据管理</li><li>B．数据治理</li><li>C．项目管理</li><li>D．项目监理</li></ul><details class="quiz" data-q="13" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目管理就是将知识、技能、工具与技术应用于项目活动，以满足项目的要求。</p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> 时间、成本、范围和（ ）等项目管理测量指标，历来被视为确定项目是否成功的最重要的因素</p><ul><li>A．沟通</li><li>B．质量</li><li>C．资源</li><li>D．风险</li></ul><details class="quiz" data-q="14" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：时间、成本、范围和质量等项目管理测量指标，历来被视为确定项目是否成功的最重要的因素。</p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> 关于项目的描述，不正确的是（ ）。</p><ul><li>A．时间、成本、范围和质量等项目管理测量指标，历来被视为确定项目是否成功的最重要的因素。确定项目是否成功还应考虑项目目标的实现情况</li><li>B．一个项目从范围、进度、预算来看是成功的，从业务角度来看应该也是成功的</li><li>C．项目管理就是将知识、技能、工具与技术应用于项目活动，以满足项目的要求</li><li>D．项目是组织创造价值和效益的主要方式</li></ul><details class="quiz" data-q="15" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：有可能一个项目从范围、进度、预算来看是成功的，但从业务角度来看并不成功，这是因为业务需求或市场环境在项目完成之前发生了变化。</p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 从项目、项目集、项目组合管理的目标来看，（ ）注重于开展“正确”的工作，即“做正确的事”</p><ul><li>A．项目组合管理</li><li>B．单个项目管理</li><li>C．大项目管理</li><li>D．项目集管理</li></ul><details class="quiz" data-q="16" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：从组织的角度看：① 项目和项目集管理的重点在于以“正确”的方式开展项目集和项目，即“正确地做事”；② 项目组合管理则注重于开展“正确”的项目集和项目，即“做正确的事”</p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 关于项目、项目集、项目组合的描述，不正确的是（ ）。</p><ul><li>A．一个项目可以采用三种不同的模式进行管理</li><li>B．项目集是一组相互关联且被协调管理的项目、子项目集和项目集活动</li><li>C．只有那些大项目才能成为项目集管理</li><li>D．项目组合的组织范围随着组织战略目标的变化而变化</li></ul><details class="quiz" data-q="17" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：为达成组织的一系列目的和目标，可能需要实施多个项目。在这种情况下，项目可能被归入项目集中。项目集是一组相互关联且被协调管理的项目、子项目集和项目集活动，目的是为了获得分别管理无法获得的利益。</p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> （ ）是一组相互关联且被协调管理的项目、子项目集和项目集活动，目的是为了获得分别管理无法获得的利益。</p><ul><li>A．项目</li><li>B．项目集</li><li>C．项目组合</li><li>D．运营管理</li></ul><details class="quiz" data-q="18" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目集是一组相互关联且被协调管理的项目、子项目集和项目集活动，目的是为了获得分别管理无法获得的利益。项目集不是大项目，大项目是指规模、影响等特别大的项目。</p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> （ ）是指为实现战略目标而组合在一起管理的项目、项目集、子项目组合和运营工作</p><ul><li>A．项目</li><li>B．项目集</li><li>C．项目组合</li><li>D．运营管理</li></ul><details class="quiz" data-q="19" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目组合是指为实现战略目标而组合在一起管理的项目、项目集、子项目组合和运营工作。</p></details><p><a id="q20" class="quiz-anchor"></a></p><p><strong>20.</strong> 关于项目、项目集和项目组合的描述，正确的是（ ）。</p><ul><li>A．项目集管理和项目组合管理的生命周期、活动、目标、重点和效益都与项目管理相同</li><li>B．项目组合有利于组织了解战略目标在项目组合中的实施情况，还能适当促进项目组合项目集和项目治理的实施与协调</li><li>C．项目和项目集管理的重点在于以“正确”的方式开展项目集和项目，即“做正确的事”</li><li>D．项目组合管理则注重于开展“正确”的项目集和项目，即“正确地做事”</li></ul><details class="quiz" data-q="20" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目组合有利于组织了解战略目标在项目组合中的实施情况，还能适当促进项目组合、项目集和项目治理的实施与协调。</p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 关于项目、项目集、项目组合的核心特征，描述正确的组合是（ ）。<br> ① 项目是临时性工作，注重内部依赖关系；<br> ② 项目集是相互关联的项目集合，注重组成部分间依赖关系；<br> ③ 项目组合是为实现战略目标组合的集合，组成部分不一定相关；<br> ④ 项目集管理“做正确的事”，项目组合管理“正确地做事”；<br> ⑤ 运营管理属于项目管理范围</p><ul><li>A．①②③</li><li>B．①②④</li><li>C．①③⑤</li><li>D．②③④</li></ul><details class="quiz" data-q="21" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目是为创造独特的产品、服务或成果而进行的临时性工作，注重项目内部的依赖关系；项目集是一组相互关联且被协调管理的项目等集合，注重组成部分之间的依赖关系；项目组合是为实现战略目标而组合在一起管理的集合，其组成部分不一定存在被此依赖或直接相关的关联关系。</p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> （ ）关注产品的持续生产、服务的持续提供。</p><ul><li>A．项目集管理</li><li>B．项目管理</li><li>C．项目组合管理</li><li>D．运营管理</li></ul><details class="quiz" data-q="22" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：运营管理关注产品的持续生产、服务的持缕提供。运营管理使用最优资源满足客户要求，以保证组织或业务持续高效地运行。</p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．项目管理注重项目内部的依赖关系，以确定管理项目的最佳方法</li><li>B．项目集管理注重项目集组成部分之间的依赖关系，以确定管理这些项目的最佳方法</li><li>C．项目组合中的项目集和项目应有依赖关系</li><li>D．运营管理是另外一个领域，不属于项目管理范围</li></ul><details class="quiz" data-q="23" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：190。项目组合中的项目集或项目不一定存在彼此依赖或直接相关的关联关系。</p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> 关于运营与项目管理描述不正确的是（ ）。</p><ul><li>A．运营的改变可以作为某个项目的关注焦点，尤其当项目交付的新产品或新服务将导致运营有实质性改变时</li><li>B．持续运营属于项目的范畴</li><li>C．在每个交叉点，可交付成果及知识都会在项目与运营之间转移</li><li>D．可能是将项目资源及知识转移到运营部门，也可能是将运营资源转移至项目中</li></ul><details class="quiz" data-q="24" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：A、C、D 是书中原话，运营管理是另外一个领域，不陋于项目管理范围。</p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 关于组织级项目管理和战略的描述，不正确的是（ ）。</p><ul><li>A．项目组合、项目集和项目都不需要符合组织战略，由组织战略驱动，并以不同的方式服务于战略目标的实现</li><li>B．项目组合管理通过选择适当的项目集或项目，对工作进行优先级排序，并提供所需资源与组织战略保持一致</li><li>C．项目集管理通过对其组成部分进行协调，对它们之间的依赖关系进行控制，从而实现既定收益</li><li>D．项目管理使组织的目标得以实现</li></ul><details class="quiz" data-q="25" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：B、C、D 是书中原话，A 应该是项目组合、项目集和项目都需要符合组组战整，由组织战略驱动，并以不同的方式服务于战略目标的实现。</p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 以下关于项目集、项目组合、项目的关系，说法错误的是（ ）</p><ul><li>A．一个项目可以采用三种不同的模式进行管理：独立项目、在项目集内、在项目组合内</li><li>B．项目组合中的项目集和项目不一定有依赖关系</li><li>C．项目组合和项目集中都可能包含日常运作业务</li><li>D．项目集管理通过选择适当的项目组合或项目，对工作进行优先级排序</li></ul><details class="quiz" data-q="26" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目组合、项目集和项目都需要符合组织战略，由组织战略驱动，并以不同的方式服务于战略目标的实现：<br> ① 项目组合管理通过选择适当的项目集或项目，对工作进行优先级排序，并提供所需资源，与组织战略保持一致；<br> ② 项目集管理通过对其组成部分进行协调，对它们之间的依赖关系进行控制，从而实现既定收益；<br> ③ 项目管理使组织的目标得以实现。</p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> （ ）则注重于开展“正确”的项目集和项目，即“做正确的事”，（ ）的重点在于以“正确”的方式开展项目集和项目，即“正确地做事”。</p><ul><li>A．项目组合、项目集和项目</li><li>B．项目集和项目、项目组合</li><li>C．项目集、项目</li><li>D．项目、项目集</li></ul><details class="quiz" data-q="27" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：从组织的角度看：① 项目和项目集管理的重点在于以“正确”的方式开展项目集和项目，即“正确地做事”；② 项目组合管理则注重于开展“正确”的项目集和项目即“做正确的事”。</p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> 关于项目组合和项目集的描述，不正确的是（ ）。</p><ul><li>A．项目组合和项目集中都可能包含日常运作业务</li><li>B．项目集是项目组合的一部分</li><li>C．项目组合中的项目既可以位于项目集之内，也可以位于项目集之外</li><li>D．项目组合中的项目集和项目应有依赖关系</li></ul><details class="quiz" data-q="28" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「项目组合中的项目集和项目应有依赖关系」，原解析未给课本依据。</p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> （ ）重在对项目进行优先级排序，并提供所需资源，与组织战略保持一致；（ ）通过对其组成部分进行协调，对它们之间的依赖关系进行控制，从而实现既定收益。</p><ul><li>A．项目集管理、组织级项目管理</li><li>B．项目组合管理、组织级项目管理</li><li>C．项目集管理、项目组合管理</li><li>D．项目组合管理、项目集管理</li></ul><details class="quiz" data-q="29" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目组合、项目集和项目都需要符合组织战略，由组织战略驱动，并以不同的方式服务于战略目标的实现：① 项目组合管理通过选择适当的项目集或项目，对工作进行优先级排序，并提供所需资源，与组织战略保持一致；② 项目集管理通过对其组成部分进行协遇，对它们之间的依赖关系进行控制，从而实现既定收益；③ 项目管理使组织的目标得以实现。</p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> 关于项目集和项目组合的描述，不正确的是（ ）。</p><ul><li>A．项目组合是为实现项目目标而组合在一起管理的项目集、子项目组合和运营工作</li><li>B．项目集将一个大型复杂项目拆分后形成的若干小项目的集合</li><li>C．项目组合经理通过项目组合的总体投资效果和实现效益来衡量项目组合的成功</li><li>D．项目集经理通过协调项目及组件的活动，确保项目集效益按预期实现</li></ul><details class="quiz" data-q="30" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目组合是为实现战略目标而组合在一起管理的项目、项目集、子项目组合和运营工作的集合。</p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> 关于项目组合战略目标，以下说法错误的是（ ）。</p><ul><li>A．项目交付和战略目标是相对独立的</li><li>B．项目组合管理通过选择适当的项目集或项目，与组织战略保持一致。</li><li>C．项目集管理通过协调组成部分和控制依赖关系，实现既定收益</li><li>D．项目管理是使组织战略目标得以实现的基础。</li></ul><details class="quiz" data-q="31" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目组合、项目集和项目都需要符合组织战略，由组织战略驱动，并以不同的方式服务于战略目标的实现：<br> ① 项目组合管理通过选择适当的项目集或项目，对工作进行优先级排序，并提供所需资源，与组组战略保持一致；<br> ② 项目集管理通过对其组成部分进行协调，对它们之间的依赖关系进行控制，从而实现既定收益；<br> ③ 项目管理使组织的目标得以实现。</p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> （ ）PMO 直接管理和控制项目。项目经理由 PMO 指定并向其报告。这种类型的 PMO 对项目的控制程度很高。</p><ul><li>A．指令型</li><li>B．支持型</li><li>C．控制型</li><li>D．组合型</li></ul><details class="quiz" data-q="32" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：PMO 有如下几种不同类型：<br> 1、支持型：支持型 PMO 担当顾间的角色。这种类型的 PMO 其实就是一个项目资源库，对项目的控制程度很弱；<br> 2、控制型：控制型 PMO 对项目的控制程度属于中等；<br> 3、指令型：指令型 PMO 直接管理和控制项目。项目经理由 PMO 指定并向其报告。这种类型的 PMO 对项目的控制程度很高。</p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> 关于项目管理办公室 PMO 的几点说法，正确的是（ ）。</p><ul><li>A．支持型 PMO 其实就是一个项目资源库，对项目的控制程度很弱</li><li>B．控制型 PMO 直接管理和控制项目，项目经理由 PMO 指定并向其报告</li><li>C．为了保证项目符合组织的业务目标，PMO 支持和管理的项目之间都会彼此关联</li><li>D．在强矩阵型组织结构中，项目经理的职权比 PMO 型的要高</li></ul><details class="quiz" data-q="33" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：PMO 有如下几种不同类型：<br> 1、支持型：支持型 PMO 担当顾间的角色。这种类型的 PMO 其实就是一个项目资源库，对项目的控制程度很弱；<br> 2、控制型：控制型 PMO 对项目的控制程度属于中等；<br> 3、指令型：指令型 PMO 直接管理和控制项目。项目经理由 PMO 指定并向其报告。这种类型的 PMO 对项目的控制程度很高。</p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> （ ）PMO 其实就是一个项目资源库，对项目的控制程度很低</p><ul><li>A．指令型</li><li>B．支持型</li><li>C．控制型</li><li>D．组合型</li></ul><details class="quiz" data-q="34" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：考点：PMO 有如下几种不同类型：<br> 1、支持型：支持型 PMO 担当顾间的角色。这种类型的 PMO 其实就是一个项目资源库，对项目的控制程度很弱；<br> 2、控制型：控制型 PMO 对项目的控制程度属于中等；<br> 3、指令型：指令型 PMO 直接管理和控制项目。项目经理由 PMO 指定并向其报告。这种类型的 PMO 对项目的控制程度很高。</p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> （ ）PMO 不仅给项目提供支持，而且通过各种手段要求项目服从。</p><ul><li>A．指令型</li><li>B．支持型</li><li>C．控制型</li><li>D．组合型</li></ul><details class="quiz" data-q="35" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：考点：PMO 有如下几种不同类型：<br> 1、支持型：支持型 PMO 担当顾间的角色。这种类型的 PMO 其实就是一个项目资源库，对项目的控制程度很弱；<br> 2、控制型：控制型 PMO 对项目的控制程度属于中等；<br> 3、指令型：指令型 PMO 直接管理和控制项目。项目经理由 PMO 指定并向其报告。这种类型的 PMO 对项目的控制程度很高。</p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> 以下说法中，错误的是（ ）。</p><ul><li>A．控制型 PMO 直接管理和控制项目。项目经理由 PMO 指定并向其报告。这种类型的 PMO 对项目的控制程度很高</li><li>B．通过项目审计，监督项目对项目管理标准、政策、程序和模板的合规性是 PMO 的职责之一</li><li>C．项目生命周期指项目从启动到完成所经历的一系列阶段，这些阶段之间的关系可以顺序、迭代或交叠进行</li><li>D．项目管理过程组不同于项目阶段，项目管理过程组是为了管理项目，针对项目管理过程进行逻辑上的划分</li></ul><details class="quiz" data-q="36" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：考点：PMO 有如下几种不同类型：<br> 1、支持型：支持型 PMO 担当顾间的角色。这种类型的 PMO 其实就是一个项目资源库，对项目的控制程度很弱；<br> 2、控制型：控制型 PMO 对项目的控制程度属于中等；<br> 3、指令型：指令型 PMO 直接管理和控制项目。项目经理由 PMO 指定并向其报告。这种类型的 PMO 对项目的控制程度很高。</p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 以下关于项目管理和产品管理之间的关系，描述错误的是（ ）。</p><ul><li>A．初始产品开始时可以是项目集或项目的可交付物。在某些情况下，项目集可以涵盖产品（或服务）的整个生命周期，以便更直接地管理收益并为组织创造价值</li><li>B．产品生命周期中包含项目集管理</li><li>C．产品生命周期中包含单个项目管理</li><li>D．单个项目管理有时也包含产品运营管理，比如运维和售后</li></ul><details class="quiz" data-q="37" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：A、B、C 是课本原话。运营管理是另外一个领域，不属于项目管理范围。</p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 产品生命周期是指一个产品从（ ）到衰退的整个演变过程的一系列阶段</p><ul><li>A．引入、成长、成熟</li><li>B．研发、测试、发布</li><li>C．设计、生产、销售</li><li>D．规划、实施、运维</li></ul><details class="quiz" data-q="38" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：产品生命周期是指一个产品从引入、成长、成熟到衰退的整个演变过程的一系列阶段。</p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．项目经理由执行组织委派，负责领导团队实现项目目标</li><li>B．职能经理：专注于对某个职能领域或业务部门的管理监督</li><li>C．运营经理：负责保证业务运营的高效性</li><li>D．只有在项目启动、项目经理收到委托后，才会参与项目评估和分析活动</li></ul><details class="quiz" data-q="39" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理可能会在项目启动之前就参与评估和分析活动。</p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> 成功的项目经理可以持续、有效地使用一些必要技能，下面不是项目经理必要技能的是（ ）</p><ul><li>A．人际关系</li><li>B．沟通技能</li><li>C．专业技术</li><li>D．积极的态度</li></ul><details class="quiz" data-q="40" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：成功的项目经理可以持续、有效地使用一些必要技能，包括人际关系、沟通技能和积极的态度。</p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> 项目经理使用（ ）来平衡项目干系人之间相互冲突和竞争的目标，以达成共识。</p><ul><li>A．软技能</li><li>B．专业知识</li><li>C．项目管理理论</li><li>D．领导力</li></ul><details class="quiz" data-q="41" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目经理使用软技能（例如人际关系技能、人员管理技能）来平衡项目干系人之间相互冲突和竞争的目标，以达成共识。</p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> 其他独立项目或同一项目集的其他项目可能因为一些原因对项目造成影响，这些原因不包括（ ）</p><ul><li>A．对相同资源的需求</li><li>B．相关的设计制约</li><li>C．可交付成果的接受或发布</li><li>D．项目与组织战略和目标的一致性</li></ul><details class="quiz" data-q="42" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：其他独立项目或同一项目集的其他项目可能因为一些原因对项目造成影响，这些原因包括：<br> ① 对相同资源的需求；<br> ② 资金分配的优先顺序；<br> ③ 可交付成果的接受或发布；<br> ④ 项目与组织战略和目标的一致性。</p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> 以下说法中，不正确的是（ ）。</p><ul><li>A．项目经理还应该：① 展现项目管理的价值；② 提高组织对项目管理的接受度；③ 提高组织内现有 PMO 的效率。</li><li>B．项目经理可能与其他项目经理一起，向 PMO、项目组合或项目集经理报告。</li><li>C．项目经理需要和职能经理经常沟通，但是不用向其报告</li><li>D．在某些情况下，项目经理可以是临时被委任的外部顾问。</li></ul><details class="quiz" data-q="43" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：基于组织结构，项目经理有可能向职能经理报告。而在其他情况下，项目经理可能与其他项目经理一起，向 PMO、项目组合或项目集经理报告。</p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> （ ）对整个组织范围内的一个或多个项目承担最终责任。</p><ul><li>A．项目经理</li><li>B．职能经理</li><li>C．运营经理</li><li>D．PMO</li></ul><details class="quiz" data-q="44" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：PMO、项目组合或项目集经理对整个组织范围内的一个或多个项目承担最终责任。</p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 关于项目经理的描述，不正确的是（ ）。</p><ul><li>A．项目经理是发起人、团队成员与其他干系人之间的沟通者</li><li>B．项目经理领导项目团队实现项目目标</li><li>C．项目经理应该时刻关注行业的最新发展趋势</li><li>D．项目经理不可以是临时被委任的外部顾问</li></ul><details class="quiz" data-q="45" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理还需与其他角色紧密协作，如组织经理、专家以及可行性研究分析人员。在某些情况下，项目经理可以是临时被委任的外部顾问。</p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> 关于项目经理的职责，描述正确的是（ ）。</p><ul><li>A．对组织内多个项目组合的最终成果承担管理责任，并独立制定项目集战略</li><li>B．负责制定组织的长期战略目标并协调各部门资源</li><li>C．监督某个职能部门的日常运营，确保业务高效执行</li><li>D．领导项目团队实现项目目标和干系人的期望</li></ul><details class="quiz" data-q="46" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理领导项目团队实现项目目标和干系人的期望。项目经理利用可用资源，平衡相互竟争的制约因素。</p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> 关于项目经理影响力，不正确的是（ ）。</p><ul><li>A．项目经理不需要向职能经理汇报</li><li>B．项目经理需利用软技能平衡干系人之间相互冲突的目标以达成共识</li><li>C．项目经理应关注最新发展趋势并判断其对当前项目的影响</li><li>D．项目经理可以是临时被委任的外部顾问</li></ul><details class="quiz" data-q="47" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：基于组织结构，项目经理有可能向职能经理报告。而在其他情况下，项目经理可能与其他项目经理一起，向 PMO、项目组合或项目集经理报告。</p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> 针对领导力和管理二者的区别，属于领导力的特征的是（ ）。</p><ul><li>A．直接利用职位</li><li>B．关注系统和架构</li><li>C．关注可操作性的问题和问题的解决</li><li>D．激发信任</li></ul><details class="quiz" data-q="48" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：</p><table><thead><tr><th>管理</th><th>领导力</th></tr></thead><tbody><tr><td>直接利用职位权力</td><td>利用关系的力量指导、影响与合作</td></tr><tr><td>维护</td><td>建设</td></tr><tr><td>管理</td><td>创新</td></tr><tr><td>关注系统和架构</td><td>关注人际关系</td></tr><tr><td>依赖控制</td><td>激发信任</td></tr><tr><td>关注近期目标</td><td>关注长期愿景</td></tr><tr><td>了解方式和时间</td><td>了解情况和原因</td></tr><tr><td>关注赢利</td><td>关注范围</td></tr><tr><td>接受现状</td><td>挑战现状</td></tr><tr><td>正确地做事</td><td>做正确的事</td></tr><tr><td>关注可操作性的问题和问题的解决</td><td>关注愿景、一致性、动力和激励</td></tr></tbody></table></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> 关于项目经理的角色，下列描述中正确的是（ ）</p><ul><li>A．项目经理应该是团队中技术最强的人</li><li>B．项目经理应该由项目发起人担任</li><li>C．项目经理应该具有项目管理的经历和经验</li><li>D．项目经理就是项目的总工程师</li></ul><details class="quiz" data-q="49" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目经理首先应该具备类似项目的项目实施经验，同时对该行业的相关知识有扎实的基础。然悉和了解项目中的每一项技术，才能全面掌握项目，应具有协调、组织的能力，应具有沟通、协调的能力。</p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> 项目经理需要重点关注三个方面的关键技能包括（ ）。</p><ul><li>A．项目管理、战略和商务、沟通力</li><li>B．项目管理、情商、领导力</li><li>C．项目管理、沟通力、领导力</li><li>D．项目管理、战略和商务、领导力</li></ul><details class="quiz" data-q="50" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理需要重点关注三个方面的关键技能包括项目管理、战略和商务、领导力。</p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> （ ）指导、激励和带领团队所需的知识、技能和行为，可以帮助组织达成业务目标</p><ul><li>A．项目管理</li><li>B．战略和商务</li><li>C．学习最流行的开发技术</li><li>D．领导力</li></ul><details class="quiz" data-q="51" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：领导力指导、激励和带领团队所需的知识、技能和行为，可以帮助组织达成业务目标。</p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> （ ）指挥一个人执行一系列已知的预期行为从一个位置到另一个位置。（ ）指通过讨论或辩论方式与他人合作，带领他们从一个位置到另一个位置。<br> ① 人际关系技能；<br> ② 沟通；<br> ③ 管理；<br> ④ 领导力。</p><ul><li>A．①②</li><li>B．①③</li><li>C．②③</li><li>D．③④</li></ul><details class="quiz" data-q="52" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：<br> “领导力”不等同于“管理”。<br> “管理”指指挥一个人执行一系列已知的预期行为从一个位置到另一个位置。<br> “领导力”指通过讨论或辩论方式与他人合作，带领他们从一个位置到另一个位置。</p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> 关于领导力与管理的描述，不正确的是（ ）。</p><ul><li>A．管理指指挥一个人执行一系列已知的预期行为从一个位置到另一个位置</li><li>B．领导力指通过讨论或辩论方式与他人合作，带领他们从一个位置到另一个位置</li><li>C．为获得成功，项目经理必须注重管理能力的锻炼，领导力可以在项目中成长</li><li>D．直接利用职位权力属于管理</li></ul><details class="quiz" data-q="53" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：为获得成功，项目经理必须同时采用领导力和管理这西种方式。</p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作的能力是（ ）领导力风格。</p><ul><li>A．服务型</li><li>B．交易型</li><li>C．变单型</li><li>D．魅力型</li></ul><details class="quiz" data-q="54" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：</p><table><thead><tr><th>序号</th><th>领导力风格</th><th>特点描述</th></tr></thead><tbody><tr><td>①</td><td>放任型</td><td>允许团队自主决策和设定目标，又被称为“无为而治型”</td></tr><tr><td>②</td><td>交易型</td><td>根据目标、反馈和成就给予奖励</td></tr><tr><td>③</td><td>服务型</td><td>做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导</td></tr><tr><td>④</td><td>变革型</td><td>通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力</td></tr><tr><td>⑤</td><td>魅力型</td><td>能够激励他人；精神饱满、热情洋溢、充满自信；说服力强</td></tr><tr><td>⑥</td><td>交互型</td><td>结合了交易型、变革型和魅力型领导的特点</td></tr></tbody></table></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> 通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力是（ ）领导力风格。</p><ul><li>A．放任型</li><li>B．交易型</li><li>C．变革型</li><li>D．魅力型</li></ul><details class="quiz" data-q="55" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：</p><table><thead><tr><th>序号</th><th>领导力风格</th><th>特点描述</th></tr></thead><tbody><tr><td>①</td><td>放任型</td><td>允许团队自主决策和设定目标，又被称为“无为而治型”</td></tr><tr><td>②</td><td>交易型</td><td>根据目标、反馈和成就给予奖励</td></tr><tr><td>③</td><td>服务型</td><td>做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导</td></tr><tr><td>④</td><td>变革型</td><td>通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力</td></tr><tr><td>⑤</td><td>魅力型</td><td>能够激励他人；精神饱满、热情洋溢、充满自信；说服力强</td></tr><tr><td>⑥</td><td>交互型</td><td>结合了交易型、变革型和魅力型领导的特点</td></tr></tbody></table></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> 能够激励他人；精神饱满、热情洋溢、充满自信；说服力强的能力是（ ）领导力风格</p><ul><li>A．放任型</li><li>B．交易型</li><li>C．变革型</li><li>D．魅力型</li></ul><details class="quiz" data-q="56" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：</p><table><thead><tr><th>序号</th><th>领导力风格</th><th>特点描述</th></tr></thead><tbody><tr><td>①</td><td>放任型</td><td>允许团队自主决策和设定目标，又被称为“无为而治型”</td></tr><tr><td>②</td><td>交易型</td><td>根据目标、反馈和成就给予奖励</td></tr><tr><td>③</td><td>服务型</td><td>做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导</td></tr><tr><td>④</td><td>变革型</td><td>通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力</td></tr><tr><td>⑤</td><td>魅力型</td><td>能够激励他人；精神饱满、热情洋溢、充满自信；说服力强</td></tr><tr><td>⑥</td><td>交互型</td><td>结合了交易型、变革型和魅力型领导的特点</td></tr></tbody></table></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 无为而治型”是（ ）领导力风格。</p><ul><li>A．放任型</li><li>B．交易型</li><li>C．变革型</li><li>D．魅力型</li></ul><details class="quiz" data-q="57" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：</p><table><thead><tr><th>序号</th><th>领导力风格</th><th>特点描述</th></tr></thead><tbody><tr><td>①</td><td>放任型</td><td>允许团队自主决策和设定目标，又被称为“无为而治型”</td></tr><tr><td>②</td><td>交易型</td><td>根据目标、反馈和成就给予奖励</td></tr><tr><td>③</td><td>服务型</td><td>做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导</td></tr><tr><td>④</td><td>变革型</td><td>通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力</td></tr><tr><td>⑤</td><td>魅力型</td><td>能够激励他人；精神饱满、热情洋溢、充满自信；说服力强</td></tr><tr><td>⑥</td><td>交互型</td><td>结合了交易型、变革型和魅力型领导的特点</td></tr></tbody></table></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> （ ）领导风格注重个人关怀，提高追随者的能力，而（ ）领导风格关注人际关系、团体与合作，服务优先于领导。</p><ul><li>A．变革型、服务型</li><li>B．魅力型、服务型</li><li>C．服务型、变革型</li><li>D．交易型、变革型</li></ul><details class="quiz" data-q="58" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：</p><table><thead><tr><th>序号</th><th>领导力风格</th><th>特点描述</th></tr></thead><tbody><tr><td>①</td><td>放任型</td><td>允许团队自主决策和设定目标，又被称为“无为而治型”</td></tr><tr><td>②</td><td>交易型</td><td>根据目标、反馈和成就给予奖励</td></tr><tr><td>③</td><td>服务型</td><td>做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导</td></tr><tr><td>④</td><td>变革型</td><td>通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力</td></tr><tr><td>⑤</td><td>魅力型</td><td>能够激励他人；精神饱满、热情洋溢、充满自信；说服力强</td></tr><tr><td>⑥</td><td>交互型</td><td>结合了交易型、变革型和魅力型领导的特点</td></tr></tbody></table></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> 关于项目经理领导力风格、管理与领导力区别的描述，不正确的是（ ）。</p><ul><li>A．放任型领导力风格允许团队自主决策和设定目标，又称“无为而治型”</li><li>B．管理关注近期目标，领导力关注长期愿景</li><li>C．交易型领导力结合了交易型、变革型和魅力型领导的特点</li><li>D．管理侧重“正确地做事”，领导力侧重“做正确的事”</li></ul><details class="quiz" data-q="59" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：</p><table><thead><tr><th>序号</th><th>领导力风格</th><th>特点描述</th></tr></thead><tbody><tr><td>①</td><td>放任型</td><td>允许团队自主决策和设定目标，又被称为“无为而治型”</td></tr><tr><td>②</td><td>交易型</td><td>根据目标、反馈和成就给予奖励</td></tr><tr><td>③</td><td>服务型</td><td>做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导</td></tr><tr><td>④</td><td>变革型</td><td>通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力</td></tr><tr><td>⑤</td><td>魅力型</td><td>能够激励他人；精神饱满、热情洋溢、充满自信；说服力强</td></tr><tr><td>⑥</td><td>交互型</td><td>结合了交易型、变革型和魅力型领导的特点</td></tr></tbody></table></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> 关于项目经理相关能力的描述，不正确的是（ ）。</p><ul><li>A．项目管理、战略和商务、领导力是项目经理需要关注的技能</li><li>B．人际交往占据项目经理的绝大部分工作内容</li><li>C．领导力关注近期目标，关注可操作性的问题和问题的解决</li><li>D．战略和商务技能有助于项目经理了解与项目相关的商业因素</li></ul><details class="quiz" data-q="60" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目经理需要重点关注三个方面的关键技能包括项目管理、战略和商务、领导力。这些技能有助于支持更长远的战略目标，实现赢利。为了最有效地开展工作，项目经理需要平衡这三种技能。</p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> 做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导是（ ）。</p><ul><li>A．放任型</li><li>B．交易型</li><li>C．服务型</li><li>D．魅力型</li></ul><details class="quiz" data-q="61" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：</p><table><thead><tr><th>序号</th><th>领导力风格</th><th>特点描述</th></tr></thead><tbody><tr><td>①</td><td>放任型</td><td>允许团队自主决策和设定目标，又被称为“无为而治型”</td></tr><tr><td>②</td><td>交易型</td><td>根据目标、反馈和成就给予奖励</td></tr><tr><td>③</td><td>服务型</td><td>做出服务承诺，处处先为他人着想；关注他人的成长、学习、发展、自主性和福利；关注人际关系、团体与合作；服务优先于领导</td></tr><tr><td>④</td><td>变革型</td><td>通过理想化特质和行为、鼓舞性激励、促进创新和创造，以及个人关怀提高追随者的能力</td></tr><tr><td>⑤</td><td>魅力型</td><td>能够激励他人；精神饱满、热情洋溢、充满自信；说服力强</td></tr><tr><td>⑥</td><td>交互型</td><td>结合了交易型、变革型和魅力型领导的特点</td></tr></tbody></table></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> 价值驱动的项目管理知识体系关注价值的实现，包含了项目管理原则、绩效域、项目生命周期过程组、十大知识领域和价值交付系统，其中（ ）是基础，是所有项目干系人在整个项目生命周期过程中各项活动的行动指南。</p><ul><li>A．项目生命周期</li><li>B．项目管理原则</li><li>C．绩效域</li><li>D．价值交付系统</li></ul><details class="quiz" data-q="62" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目管理原则是基础，是所有项目干系人在整个项目生命周期过程中各项活动的行动指南。</p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> 项目管理原则不包括（ ）。</p><ul><li>A．营造协作的项目团队环境</li><li>B．聚焦于战略目标的实现</li><li>C．将质量融入到过程和成果中</li><li>D．为实现目标而驱动变革</li></ul><details class="quiz" data-q="63" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目管理原则包括：<br> ① 勤勉、整重和关心他人；<br> ② 营造协作的项目团队环境；<br> ③ 促进干系人有效参与；<br> ④ 聚焦于价值；<br> ⑤ 识别、评估和响应系统交互；<br> ⑥ 展现领导力行为；<br> ⑦ 根据环境进行裁剪；<br> ⑧ 将质量融入到过程和成果中；<br> ⑨ 驾驭复杂性；<br> ⑩ 优化风险应对；<br> ⑪ 拥抱适应性和韧性；<br> ⑫ 为实现目标面驱动变革。</p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> 以下关于项目价值的说法中，错误的是（ ）。</p><ul><li>A．价值是指某种事物的作用、重要性或实用性。</li><li>B．价值是项目的最终成功指标和驱动因素。</li><li>C．项目的价值只可表现为财务收益值，不可表现为所取得的公共利益和社会收益</li><li>D．价值通过可交付物的预期成果来体现。项目的目的就是提供预期的成果，预期的成果通过有价值的解决方案来实现。可通过商业论证方式，从定性或定量方面说明项目成果的预期价值</li></ul><details class="quiz" data-q="64" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目的价值具体可表现为财务收益值，也可表现为所取得的公共利益和社会收益。</p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> （ ）的特点是先基于初始需求制订一套高层级的计划，再逐渐把需求细化到适合特定的规划周期所需的详细程度。</p><ul><li>A．预测型项目生命周期</li><li>B．混合型项目生命周期</li><li>C．适应型项目生命周期</li><li>D．迭代型项目生命周期</li></ul><details class="quiz" data-q="65" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：适应型生命周期。采用适应型开发方法的项目又称敏捷型或变更驱动型项目，适合于需求不确定，不断发展变化的项目。在每次迭代前，项目和产品愿景的范围被明确定义和批准，每次迭代（又称“冲刺”）结束时，客户会对具有功能性的可交付物进行审查。</p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 所有项目都呈现包含启动项目、组织与准备、（ ）和结束项目4个项目阶段的通用的生命周期结构。</p><ul><li>A．规划项目工作</li><li>B．执行项目工作</li><li>C．监控项目工作</li><li>D．消亡</li></ul><details class="quiz" data-q="66" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：所有项目都呈现包含应动项目、组组与准备、执行项目工作和结来项目 4 个项目阶段的通用的生命周期结构。</p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> （ ）的特点是在生命周期的早期阶段确定项目范围、时间和成本，对任何范围的变更都要进行严格管理，每个阶段只进行一次，每个阶段都侧重于某一特定类型的工作。</p><ul><li>A．预测型项目生命周期</li><li>B．混合型项目生命周期</li><li>C．适应型项目生命周期</li><li>D．迭代型项目生命周期</li></ul><details class="quiz" data-q="67" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：预测型生命周期。适用于已经充分了解并明确确定需求的项目，又称为瀑布型生命周期。预测型生命周期在生命周期的早期阶段确定项目范围、时间和成本，对任何范围的变更都要进行严格管理，每个阶段只进行一次，每个阶段都侧重于某一特定类型的工作。</p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> 关于项目生命周期的核心要求及不同类型的适用场景，描述正确的是（ ）。</p><ul><li>A．适应型生命周期的项目范围通常在项目生命周期的早期确定，但时间及成本会随着项目团队对产品理解的不断深入而定期修改</li><li>B．适应型生命周期在每次迭代结束时，客户会对功能性可交付物进行审查</li><li>C．预测型生命周期分次交付整体项目或产品的各个子集</li><li>D．增量型生命周期的可交付成果在每次迭代后均为完整可用的最终产品</li></ul><details class="quiz" data-q="68" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：A不正确。送代型生命周期的项目范围通常在项目生命周期的早期确定，但时间及成本会随着项目团队对产品理解的不断深入而定期修改。</p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> 以下关于各生命周期的说法，错误的是（ ）。</p><ul><li>A．预测型生命周期，需求在开发前预先确定</li><li>B．适应型生命周期需要频繁交付对客户有价值的各个子集</li><li>C．关键干系人定期参与是适应型生命周期的特点</li><li>D．定期把变更融入项目是迭代型与增量型生命周期的特点</li></ul><details class="quiz" data-q="69" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在适应型生命周期中，关键干系人持续参与项目。</p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> 采用（ ）开发方法的项目，适合于需求不确定，不断发展变化的项目。在每次迭代前，项目和产品愿景的范围被明确定义和批准，每次送代（又称“冲刺”）结束时，客户会对具有功能性的可交付物进行审查。审查时关键干系人会提供反馈，项目团队会更新项目待办事项列表，以确定下一次迭代中特性和功能的优先级。</p><ul><li>A．增量型</li><li>B．混合型</li><li>C．迭代型</li><li>D．适应型（敏捷型）</li></ul><details class="quiz" data-q="70" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：采用适应型开发方法的项目又称敏捷型或变更驱动型项目，适合于需求不确定，不断发展变化的项目。在每次迭代前，项目和产品愿景的范围被明确定义和批准，每次迭代结束时，客户会对具有功能性的可交付物进行审查。</p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> （ ）的特点是通过在预定的时间区间内渐进增加产品功能的一系列迭代来产出可交付成果。只有在最后一次迭代之后，可交付成果具有了必要和足够的能力，才能被视为完整的。</p><ul><li>A．预测型项目生命周期</li><li>B．增量型项目生命周期</li><li>C．适应型项目生命周期</li><li>D．迭代型项目生命周期</li></ul><details class="quiz" data-q="71" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：增量型生命周期。采用增量型生命周期的项目通过在预定的时间区间内渐进增加产品功能的一系列迭代来产出可交付成果。只有在最后一次法代之后，可交付成果具有了必要和足够的能力，才能被视为完整的。</p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> （ ）的特点是项目范围通常在项目生命周期的早期确定，但时间及成本会随着项目团队对产品理解的不断深入而定期修改。</p><ul><li>A．预测型项目生命周期</li><li>B．增量型项目生命周期</li><li>C．适应型项目生命周期</li><li>D．迭代型项目生命周期</li></ul><details class="quiz" data-q="72" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：迭代型生命周期。采用迭代型生金周期的项目范围通常在项目生命周期的早期确定，但时间及成本会随着项目团队对产品理解的不断深入而定期修改。</p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> 以下关于各生命周期的说法，错误的是（ ）。</p><ul><li>A．采用增量型生命周期的项目通过在预定的时间区间内渐进增加产品功能的一系列送代来产出可交付成果。只有在最后一次迭代之后，可交付成果具有了必要和足够的能力，才能被视为元整的</li><li>B．预测型生命周期在生命周期的早期阶段确定项目范围、时间和成本，对任何范围的变更都要进行严格管理，每个阶段只进行一次，每个阶段都侧重于某一特定类型的工作</li><li>C．采用适应型生命周期的项目范围通常在项目生命周期的早期确定，但时间及成本会随着项目团队对产品理解的不断深入而定期修改</li><li>D．采用适应型开发方法的项目又称敏捷型或变更驱动型项目，适合于需求不确定，不断发展变化的项目</li></ul><details class="quiz" data-q="73" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：采用迭代型生命周期的项目范围通常在项目生命周期的早期确定，但时间及成本会随着项目团队对产品理解的不断深入而定期修改。</p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> （ ）是通过一系列重复的循环活动来开发产品，而（ ）是渐进地增加产品的功能</p><ul><li>A．迭代方法、适应方法</li><li>B．增量方法、迭代方法</li><li>C．适应方法、增量方法</li><li>D．迭代方法、增量方法</li></ul><details class="quiz" data-q="74" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：迭代方法和增量方法的区别：迭代方法是通过一系列重复的循环活动来开发产品，面增量方法是渐进地增加产品的功能。</p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> 混合型生命周期是（ ）生命周期和（ ）生命周期的组合。<br> ① 预测型；② 增量型；③ 迭代型；④ 适应型（敏捷型）</p><ul><li>A．①②</li><li>B．①③</li><li>C．②③</li><li>D．①④</li></ul><details class="quiz" data-q="75" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：混合型生命周期是预测型生命周期和适应型（敏捷型）生命周期的组合。</p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> 采用（ ）开发方法的项目，适合于需求不确定，不断发展变化的项目。</p><ul><li>A．迭代型</li><li>B．适应型</li><li>C．增量型</li><li>D．预测型</li></ul><details class="quiz" data-q="76" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：采用适应型开发方法的项目又称敏捷型或变更驱动型项目，适合需求不确定，不断发展变化的项目。在每次迭代前，项目和产品愿景的范围被明确定义和批准，每次迭代（又称“冲刺”）结束时，客户会对具有功能性的可交付物进行审查。</p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> 在项目开发方法的选择中，不同的生命周期类型对关键干系人的参与模式有不同要求。以下哪种开发方法要求关键干系人“持续参与”项目（ ）。</p><ul><li>A．适应型</li><li>B．预测型</li><li>C．迭代型</li><li>D．增量型</li></ul><details class="quiz" data-q="77" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：</p><table><thead><tr><th>预测型</th><th>迭代型与增量型</th><th>适应型</th></tr></thead><tbody><tr><td>需求在开发前预先确定</td><td>需求在交付期间定期细化</td><td>需求在交付期间频繁细化</td></tr><tr><td>针对最终可交付成果制订交付计划，然后在项目结束时一次交付最终产品</td><td>分次交付整体项目或产品的各个子集</td><td>频繁交付对客户有价值的各个子集</td></tr><tr><td>尽量限制变更</td><td>定期把变更融入项目</td><td>在交付期间实时把变更融入项目</td></tr><tr><td>关键干系人在特定里程碑点参与</td><td>关键干系人定期参与</td><td>关键干系人持续参与</td></tr><tr><td>通过对基本已知的情况编制详细计划来控制风险和成本</td><td>通过用新信息逐渐细化计划来控制风险和成本</td><td>随着需求和制约因素的显现而控制风险和成本</td></tr></tbody></table></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 关于项目生命周期特征的描述，正确的是（ ）。</p><ul><li>A．项目生命周期越长，越有利于项目执行</li><li>B．风险会随着项目的执行越来越大</li><li>C．风险和不确定性在项目开始时最大，并随项目进展而减弱</li><li>D．项目生命周期应保持投入人力始终不变</li></ul><details class="quiz" data-q="78" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：A 周期越长，不确定性越大，不利于项目执行。B 风险会随着项目的执行越来越小，D 项目人力资源的投入不是一成不变的，刚开始投入人力较小，到执行期间最大，在结束的时候变小。</p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> 迭代型与增量型项目生命周期的特点是（ ）。</p><ul><li>A．需求在交付期间频繁细化，在交付期间实时把变更融入项目</li><li>B．需求在交付期间定期细化，定期把变更融入项目</li><li>C．需求在开发前确定，尽量限制变更</li><li>D．针对最终可交付成果制订交付计划，在项目结束时一次交付最终产品</li></ul><details class="quiz" data-q="79" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：</p><table><thead><tr><th>预测型</th><th>迭代型与增量型</th><th>适应型</th></tr></thead><tbody><tr><td>需求在开发前预先确定</td><td>需求在交付期间定期细化</td><td>需求在交付期间频繁细化</td></tr><tr><td>针对最终可交付成果制订交付计划，然后在项目结束时一次交付最终产品</td><td>分次交付整体项目或产品的各个子集</td><td>频繁交付对客户有价值的各个子集</td></tr><tr><td>尽量限制变更</td><td>定期把变更融入项目</td><td>在交付期间实时把变更融入项目</td></tr><tr><td>关键干系人在特定里程碑点参与</td><td>关键干系人定期参与</td><td>关键干系人持续参与</td></tr><tr><td>通过对基本已知的情况编制详细计划来控制风险和成本</td><td>通过用新信息逐渐细化计划来控制风险和成本</td><td>随着需求和制约因素的显现而控制风险和成本</td></tr></tbody></table></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> 关于项目、项目集、项目组合的描述，不正确的是（ ）</p><ul><li>A．项目组合中的项目集或项目不一定存在彼此依赖或直接相关的关联关系</li><li>B．大型电网系统所辖项目包括建设输电线路、整合配电和用户端设备等，属于项目集管理</li><li>C．项目具有明确的目标且范围在整个生命周期中渐进明细，应采用敏捷型方法管理项目</li><li>D．项目组合的成功通过项目组合的总体投资效果和实现的效益进行衡量</li></ul><details class="quiz" data-q="80" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：适应型生命周期。采用适应型开发方法的项目又称敏撞型或变更驱动型项目，适合于需求不确定，不断发展变化的项目。适应型项目生命周期的特点是先基于初始需求制定一套高层级计划，再逐渐把需求细化到适合特定规划周期所需的详细程度。</p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> （ ）不属于迭代型与增量型生命周期的特征。</p><ul><li>A．在交付期间实时把变更融入项目</li><li>B．通过用新信息逐渐细化计划来控制风险和成本</li><li>C．关键干系人定期参与</li><li>D．分次交付整体项目或产品的各个子集</li></ul><details class="quiz" data-q="81" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：</p><table><thead><tr><th>预测型</th><th>迭代型与增量型</th><th>适应型</th></tr></thead><tbody><tr><td>需求在开发前预先确定</td><td>需求在交付期间定期细化</td><td>需求在交付期间频繁细化</td></tr><tr><td>针对最终可交付成果制订交付计划，然后在项目结束时一次交付最终产品</td><td>分次交付整体项目或产品的各个子集</td><td>频繁交付对客户有价值的各个子集</td></tr><tr><td>尽量限制变更</td><td>定期把变更融入项目</td><td>在交付期间实时把变更融入项目</td></tr><tr><td>关键干系人在特定里程碑点参与</td><td>关键干系人定期参与</td><td>关键干系人持续参与</td></tr><tr><td>通过对基本已知的情况编制详细计划来控制风险和成本</td><td>通过用新信息逐渐细化计划来控制风险和成本</td><td>随着需求和制约因素的显现而控制风险和成本</td></tr></tbody></table></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 在项目管理过程中，,（ ）定义了新项目或现有项目的新阶段，</p><ul><li>A．启动过程组</li><li>B．监控过程组</li><li>C．执行过程组</li><li>D．规划过程组</li></ul><details class="quiz" data-q="82" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：启动过程组：定义了新项目或现有项目的新阶段，启动过程组授权一个项目或阶段的开始。</p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> 在项目管理过程中，（ ）明确项目范围、优化目标，并为实现目标制订行动计划</p><ul><li>A．收尾过程组</li><li>B．监控过程组</li><li>C．执行过程组</li><li>D．规划过程组</li></ul><details class="quiz" data-q="83" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：规划过程组：明确项目范围、优化目标，并为实现目标制订行动计划。</p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> 在项目管理过程中，（ ）完成项目管理计划中确定的工作，以满足项目要求。</p><ul><li>A．收尾过程组</li><li>B．监控过程组</li><li>C．执行过程组</li><li>D．规划过程组</li></ul><details class="quiz" data-q="84" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：执行过程组：完成项目管理计划中确定的工作，以满足项目要求。</p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> 以下关于启动过程组的描述，不正确的是（ ）。</p><ul><li>A．在采用适应型生命周期的项目上，启动过程通常要在每个迭代期开展</li><li>B．适应型项目无需依赖知识丰富的干系人代表</li><li>C．随着项目进展，优先级和情况会动态变化，项目制约因素和项目成功的标准也会变化</li><li>D．需要定期开展启动过程，频繁回顺和重新确认项目章程，以确保项目在最新的制约因素内朝最新的目标推进</li></ul><details class="quiz" data-q="85" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：在采用适应型生命周期的项目上，启动过程通常要在每个迭代期开展。适应型项目非常依轴知识主富的王系人代表，他们要能够持续地表达需要和意愿，并不断针对新形成的可交付成果提出反馈意见。</p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> 以下关于规划过程组的描述，正确的是（ ）。</p><ul><li>A．在高度复杂和不确定的项目中，在采用适应型生命周期的项目上，不必让过多的团队成员和干系人参与到规划过程</li><li>B．高度预测型项目范围变更很多，干系人莴刘之间有高度共识，这类项目会受益于前期的详细规划</li><li>C．适应型项目生命周期的特点是先基于初始需求制订一套高层级的计划，再逐渐把需求细化到适合特定规划周期所需的详细程度</li><li>D．预测型和迭代型生命周期在规划阶段的主要区别在于做多少规划工作，以及什么时间做</li></ul><details class="quiz" data-q="86" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在采用适应型生命周期的项目上，应该让尽可能多的团队成员和干系人参与到规划过程，以便依据广泛的信息开展规划，降低不确定性。</p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> 在项目管理过程中，（ ）跟踪、审查和调整项目进展与绩效，识别变更并启动相应的变更</p><ul><li>A．收尾过程组</li><li>B．监控过程组</li><li>C．执行过程组</li><li>D．规划过程组</li></ul><details class="quiz" data-q="87" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：监控过程组：跟踪、审查和调整项目进展与绩效，识别变更并启动相应的变更。</p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> 关于适应型项目的说法，不正确的是（ ）。</p><ul><li>A．项目章程在整个项目期间重复修改</li><li>B．项目人员持续参加</li><li>C．关键干系人代表需要频繁互动并提供反馈</li><li>D．项目制约因素和成功标准可能会随进展动态变化</li></ul><details class="quiz" data-q="88" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：在采用适应型生命周期的项目上，启动过程通常要在每个迭代期开展。适应型项目非常依赖知识丰富的干系人代表，他们要能够持续地表达需要和意愿，并不断针对新形成的可交付成果提出反馈意见。</p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> 管理项目知识属于（ ）</p><ul><li>A．启动过程组</li><li>B．规划过程组</li><li>C．执行过程组</li><li>D．监控过程组</li></ul><details class="quiz" data-q="89" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：管理项目知识属于执行过程组。</p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> 估算活动资源属于（ ）。</p><ul><li>A．启动过程组</li><li>B．规划过程组</li><li>C．执行过程组</li><li>D．监控过程组</li></ul><details class="quiz" data-q="90" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：估算活动资源属于规划过程组。</p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> 下列不属于执行过程组的是（ ）。</p><ul><li>A．实施风险应对</li><li>B．实施定量风险分析</li><li>C．实施采购</li><li>D．管理干系人参与</li></ul><details class="quiz" data-q="91" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：实施定量风险分析属于规划过程组。</p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> （ ）属于监控过程组。</p><ul><li>A．管理质量</li><li>B．获取资源</li><li>C．建设团队</li><li>D．确认范田</li></ul><details class="quiz" data-q="92" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：确认范围属于监控过程组。</p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> 下列不属于规划过程组的是（ ）。</p><ul><li>A．估算成本</li><li>B．收集需求</li><li>C．估算活动资源</li><li>D．获取资源</li></ul><details class="quiz" data-q="93" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：获取资源属于执行过程组。</p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> 可以将组成项目的各个过程归纳为5个过程组，启动过程组包括制定项目章程和（ ）两个过程</p><ul><li>A．收集需求</li><li>B．识别项目干系人</li><li>C．定义范围</li><li>D．组织项目团队</li></ul><details class="quiz" data-q="94" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：启动过程组定义并批准项目或项目阶段。包括“制定项目章程”和“识别项目干系人”两个过程。</p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> 识别项目干系人是（ ）的子过程。</p><ul><li>A．启动过程组</li><li>B．规划过程组</li><li>C．执行过程组</li><li>D．监控过程组</li></ul><details class="quiz" data-q="95" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：启动过程组定义并批淮项目或项目阶段。包括“制定项目章程”和“识别项目干系人”两个过程。</p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> （ ）识别、定义、组合、统一和协调各项目管理过程组的各个过程和活动。</p><ul><li>A．整合管理</li><li>B．范围管理</li><li>C．进度管理</li><li>D．成本管理</li></ul><details class="quiz" data-q="96" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：整合管理：识别、定义、组合、统一和协调各项目管理过程组的各个过程和活动。</p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 以下（ ）属于启动过程组的内容。</p><ul><li>A．识别干系人</li><li>B．规划进度管理</li><li>C．范围确认</li><li>D．成本预算</li></ul><details class="quiz" data-q="97" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：启动过程组定义并批准项目或项目阶段。包括“制定项目章程”和“识别项目干系人”两个过程。</p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> 关于过程组、项目管理原则、项目绩效域和领导力风格，下列说法正确的是（ ）</p><ul><li>A．规划过程组是为了完成项目管理计划中确定的工作，以满足项目要求。</li><li>B．项目管理者在遵守内部和外部准则的同时，应该以负责任的方式行事，以正直、关心和可信的态度开展活动，同时对其所负责项目的财务、社会和环境能响做出承谐。这体现了展现领导力行为的原则</li><li>C．项目绩效域是项目执行过程中需要密切关注的相互作用、相互关联和相互依赖的领域，它们可以协调一致地实现预期的项目成果</li><li>D．放任型领导关注他人的成长、学习、发展、自主性和福利</li></ul><details class="quiz" data-q="98" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目绩效域是一组对有效地交付项目成果至关重要的活动。项目绩效城是项目执行过程中蛋要密切关注的相互作用、相互关联和相互依赖的领域，它们可以协调二致地实现预期的项目成黑，共有干系人、团队、开发方法和生命周期、规划、项目工作、交付、测量、不确定性八个项目绩效域，这些绩效城共同构成了一个统一的整体。</p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> （ ）描述了项目如何在系统内运作，为组织及其干系人创造价值。价值交付系统包括项目如何创造价值、价值交付组件和信息流。</p><ul><li>A．价值交付系统</li><li>B．ERP 系统</li><li>C．CRM 系统</li><li>D．信息安全系统</li></ul><details class="quiz" data-q="99" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：价值交付系统描述了项目如何在系统内运作，为组织及其干系人创造价值。价值交付系统包括项目如何创造价值、价值交付组件和信息流。</p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> （ ）可带来收益，（ ）是组织实现的利益。收益继而可创造价值，而（ ）是具有作用、重要性或实用性的事物。</p><ul><li>A．组件、价值、成果</li><li>B．成果、收益、价值</li><li>C．成果、价值、成果</li><li>D．组件、成果、价值</li></ul><details class="quiz" data-q="100" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：成果可带来收益，收益是组织实现的利益。收益继而可创造价值，面价值是具有作用、重要性或实用性的事物。</p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> 价值交付系统中的（ ）创建了用于产出成果的可交付物。（ ）是某一过程或项目的最终结果或后果</p><ul><li>A．成果、价值</li><li>B．收益、价值</li><li>C．组件、成果</li><li>D．组件、收益</li></ul><details class="quiz" data-q="101" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：价值交付系统中的组件创建了用于产出成果的可交付物。成果是某一过程或项目的最终结果或后果。</p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 关于价值交付系统的核心特征及相关概念的关系，描述正确的是（ ）</p><ul><li>A．价值交付组件包括项目、项目集、项目组合，不包括运营</li><li>B．可交付物由价值交付系统的组件创建，用于产出成果</li><li>C．价值可直接由可交付物创造，无需经过成果和收益的转化</li><li>D．价值交付系统是组织内部环境之一，不受外部环境的影响</li></ul><details class="quiz" data-q="102" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：可以单独或共同使用多种组件（例如项目组合、项目集、项目、产品和运营）以创造价值。这些组件共同组成了一个符合组织战略的价值交付系统。</p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> 价值交付系统中的组件创建了用于产出成果的可交付物，价值交付组件不包括（ ）</p><ul><li>A．项目集</li><li>B．政策和战略</li><li>C．产品和运营</li><li>D．项目组合</li></ul><details class="quiz" data-q="103" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：可以单独或共同使用多种组件（例如项目组合、项目集、项目、产品和运营）以创造价值。这些组件共同组成了一个符合组织战略的价值交付系统。</p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 当信息和信息反馈在所有价值交付组件之间以（ ）的方式共享时，价值交付系统最为有效，能够使系统与战略保持一致。</p><ul><li>A．一致</li><li>B．及时</li><li>C．透明</li><li>D．零散</li></ul><details class="quiz" data-q="104" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：当信息和信息反馈在所有价值交付组件之间以一致的方式共享时，价值交付系统最为有效，能够使系统与战略保持一致。</p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> 价值交付系统包括项目如何创造价值、价值交付组件和信息流。其中，价值交付组件包括（ ）。<br> ① 战略；② 项目组合；③ 项目集；④ 项目；⑤ 运营；⑥ 产品；⑦ 市场环境</p><ul><li>A．②③④⑤⑥</li><li>B．②③④⑥⑦</li><li>C．①②③④⑤</li><li>D．①②③④⑥</li></ul><details class="quiz" data-q="105" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：可以单独或共同使用多种组件（例如项目组合、项目集、项目、产品和运营）来创造价值这些组件共同组成了一个符合组织战略的价值交付系统。</p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};